<?php
session_start();
header('Content-Type: application/json');

if (!isset($_SESSION['username'])) {
    http_response_code(401);
    echo json_encode(['success' => false, 'message' => 'Session expired. Please log in again.']);
    exit;
}

include "config/database.php";

$name  = trim($_POST['name'] ?? '');
$phone = trim($_POST['phone'] ?? '');

if ($name === '' || $phone === '') {
    echo json_encode(['success' => false, 'message' => 'Name and phone are required.']);
    exit;
}

// Cust_ID isn't auto-generated by the database, so work out the next one here (C001, C002, ...)
$newId = 'C001';
$result = $conn->query("SELECT Cust_ID FROM customers ORDER BY Cust_ID DESC LIMIT 1");
if ($result && $row = $result->fetch_assoc()) {
    $number = intval(substr($row['Cust_ID'], 1)) + 1;
    $newId = 'C' . str_pad($number, 3, '0', STR_PAD_LEFT);
}

$stmt = $conn->prepare("INSERT INTO customers (Cust_ID, Name, Phone) VALUES (?, ?, ?)");
$stmt->bind_param("sss", $newId, $name, $phone);

if ($stmt->execute()) {
    echo json_encode([
        'success' => true,
        'cust_id' => $newId,
        'name'    => $name,
        'phone'   => $phone
    ]);
} else {
    echo json_encode(['success' => false, 'message' => 'Could not add customer: ' . $stmt->error]);
}

$conn->close();
?>